"""Durable operator decisions beside, and never inside, the original buyer ledger."""
from __future__ import annotations

from contextlib import suppress
from pathlib import Path
import fcntl
import json
import os
import re
import sqlite3
import stat
import threading

from domain import Problem, SCHEMA, now, canonical, identifier, text, day, digest, row_key, basis, native_changes, validate_coding, period_view, spending_reservation_identity
from native import capture_source, parse_labels
from credit_store import CreditStore, CREDIT_DDL
from accountant_store import AccountantStore, ACCOUNTANT_DDL

DDL = """
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS captures(id TEXT PRIMARY KEY, source_id TEXT NOT NULL, parent_id TEXT, status TEXT NOT NULL, created_at TEXT NOT NULL, body TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS captures_source ON captures(source_id,created_at,id);
CREATE TABLE IF NOT EXISTS items(id TEXT PRIMARY KEY, source_id TEXT NOT NULL, request_id TEXT NOT NULL, capture_id TEXT NOT NULL, missing INTEGER NOT NULL, body TEXT NOT NULL, UNIQUE(source_id,request_id));
CREATE TABLE IF NOT EXISTS centers(id TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS codings(id TEXT PRIMARY KEY, item_id TEXT NOT NULL, created_at TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS coding_heads(item_id TEXT PRIMARY KEY, coding_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS periods(id TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dispositions(id TEXT PRIMARY KEY, period_id TEXT NOT NULL, item_id TEXT NOT NULL, code TEXT NOT NULL, created_at TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS disposition_heads(period_id TEXT NOT NULL,item_id TEXT NOT NULL,code TEXT NOT NULL,disposition_id TEXT NOT NULL,PRIMARY KEY(period_id,item_id,code));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, period_id TEXT NOT NULL, created_at TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS closes(id TEXT PRIMARY KEY, period_id TEXT NOT NULL, sequence INTEGER NOT NULL, created_at TEXT NOT NULL, body TEXT NOT NULL,UNIQUE(period_id,sequence));
CREATE TABLE IF NOT EXISTS events(sequence INTEGER PRIMARY KEY, created_at TEXT NOT NULL, action TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS api_requests(id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, operation TEXT NOT NULL, created_at TEXT NOT NULL, body TEXT NOT NULL);
""" + CREDIT_DDL + ACCOUNTANT_DDL


def private_directory(path):
    value = path.stat()
    if not stat.S_ISDIR(value.st_mode) or value.st_mode & 0o077 or value.st_uid != os.getuid():
        raise Problem("PRIVATE_DIRECTORY_REQUIRED", "Use an operator-owned directory with mode 0700")


def private_file(path):
    value = path.lstat()
    if not stat.S_ISREG(value.st_mode) or value.st_mode & 0o077 or value.st_uid != os.getuid():
        raise Problem("PRIVATE_FILE_REQUIRED", "Use an operator-owned regular file with mode 0600")


def page(values, offset=0, limit=50):
    if type(offset) is not int or offset < 0 or type(limit) is not int or not 1 <= limit <= 200:
        raise Problem("INVALID_PAGE", "Use a nonnegative offset and page size from 1 to 200")
    return {"items": values[offset:offset + limit], "total": len(values), "offset": offset,
            "next": offset + limit if offset + limit < len(values) else None}


class Store(CreditStore, AccountantStore):
    def __init__(self, directory, node_executable=None):
        self.root = Path(directory).expanduser().resolve()
        self.root.mkdir(mode=0o700, parents=True, exist_ok=True)
        private_directory(self.root)
        self.lock = threading.RLock()
        self.closed = False
        self.node_executable = node_executable
        self.connection = None
        self.request_context = None
        self.lease = os.open(self.root / "operator.lock", os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0), 0o600)
        try:
            private_file(self.root / "operator.lock")
            try:
                fcntl.flock(self.lease, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError as exc:
                raise Problem("WORKSPACE_IN_USE", "The original expense workspace is already open in another process", 409) from exc
            database = self.root / "workspace.sqlite"
            if database.exists():
                private_file(database)
            elif any(p.name != "operator.lock" for p in self.root.iterdir()):
                raise Problem("NEW_DIRECTORY_REQUIRED", "Create the expense workspace in a new directory, separate from the buyer ledger")
            else:
                fd = os.open(database, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                os.close(fd)
            self.connection = sqlite3.connect(database, isolation_level=None, check_same_thread=False, timeout=10)
            self.connection.row_factory = sqlite3.Row
            if database.stat().st_size:
                known = self.connection.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='meta'").fetchone()
                mark = self.connection.execute("SELECT value FROM meta WHERE key='schema'").fetchone() if known else None
                if not mark or mark[0] != SCHEMA:
                    raise Problem("WORKSPACE_SCHEMA", "This existing database is not a completed native expense workspace", 409)
            self.connection.execute("PRAGMA trusted_schema=OFF")
            self.connection.execute("PRAGMA foreign_keys=ON")
            self.connection.execute("PRAGMA journal_mode=WAL")
            self.connection.execute("PRAGMA synchronous=FULL")
            self.connection.executescript(DDL)
            found = self.connection.execute("SELECT value FROM meta WHERE key='schema'").fetchone()
            if found and found["value"] != SCHEMA:
                raise Problem("WORKSPACE_SCHEMA", "This workspace requires its original application version", 409)
            self.connection.execute("INSERT OR IGNORE INTO meta VALUES('schema',?)", (SCHEMA,))
            self.connection.execute("INSERT OR IGNORE INTO meta VALUES('revision','0')")
            self.connection.execute("INSERT OR IGNORE INTO meta VALUES('id',?)", (identifier("workspace"),))
            self.connection.execute("INSERT OR IGNORE INTO meta VALUES('labels','[]')")
            self.connection.execute("INSERT OR IGNORE INTO meta VALUES('data_context',?)",
                                    ("operational" if self.connection.execute("SELECT COUNT(*) FROM sources").fetchone()[0] else "",))
        except BaseException:
            if self.connection:
                self.connection.close()
            os.close(self.lease)
            self.closed = True
            raise

    def close(self):
        with self.lock:
            if self.closed:
                return
            self.closed = True
            try:
                self.connection.close()
            finally:
                os.close(self.lease)

    def revision(self):
        return int(self.connection.execute("SELECT value FROM meta WHERE key='revision'").fetchone()[0])

    def _get(self, table, ident):
        if table not in {"sources", "captures", "items", "centers", "codings", "periods", "reviews", "closes", "dispositions"}:
            raise AssertionError("fixed table required")
        value = self.connection.execute("SELECT body FROM " + table + " WHERE id=?", (ident,)).fetchone()
        if value is None:
            raise Problem("NOT_FOUND", "The selected retained record does not exist", 404)
        return json.loads(value[0])

    def _bodies(self, table):
        if table not in {"sources", "centers", "periods"}:
            raise AssertionError("fixed table required")
        return [json.loads(r[0]) for r in self.connection.execute("SELECT body FROM " + table + " ORDER BY id")]

    def _put(self, table, body):
        if table not in {"sources", "centers", "periods"}:
            raise AssertionError("fixed table required")
        self.connection.execute("INSERT INTO " + table + "(id,body) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET body=excluded.body",
                                (body["id"], canonical(body)))

    @staticmethod
    def request_id(value):
        if not isinstance(value, str) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}", value):
            raise Problem("REQUEST_ID", "Retain one request ID of 1 to 128 letters, numbers, dot, underscore, colon or hyphen")
        return value

    def inspect_request(self, ident):
        ident = self.request_id(ident)
        with self.lock:
            row = self.connection.execute("SELECT * FROM api_requests WHERE id=?", (ident,)).fetchone()
            if row is None:
                raise Problem("REQUEST_NOT_COMMITTED", "No successful mutation with this request ID is retained. Retry only the same original request.", 404)
            return {"id": ident, "state": "COMMITTED", "fingerprint": row["fingerprint"],
                    "operation": row["operation"], "created_at": row["created_at"], "response": json.loads(row["body"])}

    def requests(self, offset=0, limit=50):
        with self.lock:
            if type(offset) is not int or offset < 0 or type(limit) is not int or not 1 <= limit <= 200:
                raise Problem("INVALID_PAGE", "Use a nonnegative offset and a page size from 1 to 200")
            total = self.connection.execute("SELECT COUNT(*) FROM api_requests").fetchone()[0]
            rows = [dict(row) for row in self.connection.execute(
                "SELECT id,fingerprint,operation,created_at FROM api_requests ORDER BY created_at DESC,id DESC LIMIT ? OFFSET ?", (limit, offset))]
            return {"items": rows, "total": total, "offset": offset, "next": offset + limit if offset + limit < total else None}

    def perform_request(self, ident, path, payload, expected, operation):
        """The optional HTTP request identity commits in the native mutation transaction."""
        ident = self.request_id(ident)
        fingerprint = digest({"method": "POST", "path": path, "payload": payload, "expected_revision": expected})
        with self.lock:
            if self.closed:
                raise Problem("WORKSPACE_CLOSED", "The workspace is closing", 503)
            previous = self.connection.execute("SELECT fingerprint,body FROM api_requests WHERE id=?", (ident,)).fetchone()
            if previous:
                if previous["fingerprint"] != fingerprint:
                    raise Problem("REQUEST_CONFLICT", "This request ID already names different original content or revision; inspect its retained response", 409)
                return json.loads(previous["body"])
            if self.request_context is not None:
                raise Problem("REQUEST_NESTED", "Complete the current native request before opening another", 409)
            self.request_context = {"id": ident, "fingerprint": fingerprint, "operation": path}
            try:
                return operation()
            finally:
                self.request_context = None

    def _change(self, expected, action, operation):
        with self.lock:
            if self.closed:
                raise Problem("WORKSPACE_CLOSED", "The workspace is closing", 503)
            self.connection.execute("BEGIN IMMEDIATE")
            try:
                revision = self.revision()
                if type(expected) is not int or expected != revision:
                    raise Problem("WORKSPACE_CHANGED", "The workspace changed. Refresh and review your preserved form before saving again", 409)
                result = operation()
                revision += 1
                self.connection.execute("UPDATE meta SET value=? WHERE key='revision'", (str(revision),))
                self.connection.execute("INSERT INTO events(created_at,action,body) VALUES(?,?,?)",
                                        (now(), action, canonical({"revision": revision, "record": result.get("id") if isinstance(result, dict) else None})))
                response = {"revision": revision, "result": result}
                if self.request_context is not None:
                    request = self.request_context
                    response["request_id"] = request["id"]
                    self.connection.execute("INSERT INTO api_requests VALUES(?,?,?,?,?)",
                        (request["id"], request["fingerprint"], request["operation"], now(), canonical(response)))
                self.connection.execute("COMMIT")
                return response
            except BaseException:
                with suppress(sqlite3.Error):
                    if self.connection.in_transaction:
                        self.connection.execute("ROLLBACK")
                raise

    def _source_views(self):
        result = []
        for source in self._bodies("sources"):
            view = dict(source)
            view["kind"] = source.get("kind", "sf36_ledger")
            view["pending"] = [r[0] for r in self.connection.execute("SELECT id FROM captures WHERE source_id=? AND status='PENDING' ORDER BY created_at,id", (source["id"],))]
            if source.get("current_capture"):
                captured = self._get("captures", source["current_capture"])
                report = captured["report"]
                view.update(capture_time=report["captured_at"], projection_sha256=report["source"]["projection_sha256"],
                            journal_events=report["source"]["journal_events"], last_sequence=report["source"]["last_sequence"],
                            rows=report["source"].get("records", report["source"].get("reservations", 0)), portfolio=report["portfolio"],
                            record_kind=report["source"].get("record_kind", "reservations"),
                            source_basis=report.get("basis"), date_basis=report.get("date_basis"))
                if view["kind"] == "sf36_ledger":
                    view["reservation_ledger_identity"] = captured["identity"]
                if view["kind"] == "governed_mcp":
                    view["spending_owner"] = report["source"].get("spending_owner")
                    view["ledger_state"] = report["source"].get("ledger_state")
                    view["reservation_ledger_identity"] = report["source"].get("reservation_ledger_identity")
                    view["unlinked_spending_exposures"] = report["source"].get("unlinked_spending_exposures", [])
                    view["source_issues"] = report["source"].get("integrity_issues", [])
                    view["source_notes"] = report["source"].get("source_notes", [])
            result.append(view)
        return result

    def _items(self):
        names = {s["id"]: s["name"] for s in self._bodies("sources")}
        heads = {r["item_id"]: json.loads(r["body"]) for r in self.connection.execute(
            "SELECT h.item_id,c.body FROM coding_heads h JOIN codings c ON c.id=h.coding_id")}
        items = []
        for value in self.connection.execute("SELECT * FROM items ORDER BY source_id,request_id"):
            row = json.loads(value["body"])
            item = {"id": value["id"], "source_id": value["source_id"], "source_name": names[value["source_id"]],
                    "capture_id": value["capture_id"], "missing": bool(value["missing"]), "row": row}
            item["basis"] = basis(row, item["missing"])
            item["coding"] = heads.get(item["id"])
            nonexpense = {"reserved":"RESERVED", "unresolved":"PAYMENT_UNRESOLVED",
                          "failed":"FAILED_TRANSACTION", "not_dispatched":"NO_SIGNED_DISPATCH",
                          "observation_review":"OBSERVATION_REVIEW", "spending_review":"SPENDING_SOURCE_REVIEW"}
            item["status"] = ("ABSENT" if item["missing"] else nonexpense[row["state"]] if row["state"] in nonexpense else
                              "UNCODED" if not item["coding"] else "STALE" if item["coding"]["basis"] != item["basis"] else "CODED")
            items.append(item)
        return items

    def state(self):
        with self.lock:
            periods = sorted(self._bodies("periods"), key=lambda p: (p["from_day"], p["id"]), reverse=True)
            return {"schema": SCHEMA, "id": self.connection.execute("SELECT value FROM meta WHERE key='id'").fetchone()[0],
                    "revision": self.revision(), "sources": self._source_views(), "periods": periods,
                    "data_context": self._data_context(),
                    "credit_count": self.connection.execute("SELECT COUNT(*) FROM credits").fetchone()[0],
                    "accountant_return_count": self.connection.execute("SELECT COUNT(*) FROM accountant_returns").fetchone()[0],
                    "pending_refund_packets": self.connection.execute("SELECT COUNT(*) FROM refund_packets WHERE status='PENDING'").fetchone()[0],
                    "centers": self._bodies("centers"), "labels": json.loads(self.connection.execute("SELECT value FROM meta WHERE key='labels'").fetchone()[0])}

    def expenses(self, query="", source="", status="", offset=0, limit=50):
        with self.lock:
            query = text(query, "Search", maximum=300, optional=True).casefold()
            found = [i for i in self._items() if (not source or i["source_id"] == source) and (not status or i["status"] == status)
                     and (not query or query in " ".join([i["row"]["request_id"], i["source_name"], i["row"]["actor"], i["row"]["service"],
                                                         i["row"]["receipt_ref"], i.get("coding", {}).get("memo", "") if i.get("coding") else ""]).casefold())]
            return page(found, offset, limit)

    def item(self, ident):
        with self.lock:
            selected = next((i for i in self._items() if i["id"] == ident), None)
            if selected is None:
                raise Problem("NOT_FOUND", "Select an original native row", 404)
            selected["coding_history"] = [json.loads(r[0]) for r in self.connection.execute("SELECT body FROM codings WHERE item_id=? ORDER BY created_at DESC,id DESC", (ident,))]
            return selected

    def _new_capture(self, source, native, *, reattachment=None):
        captured = {"id": identifier("capture"), "source_id": source["id"], "parent_id": source.get("current_capture"),
                    "status": "PENDING", "created_at": now(), "path": native["path"], "identity": native["identity"],
                    "snapshot": native["snapshot"], "report": native["report"]}
        if reattachment is not None:
            captured["reattachment"] = reattachment | {"to_capture": captured["id"]}
        previous = self._get("captures", source["current_capture"])["report"] if source.get("current_capture") else None
        captured["changes"] = native_changes(previous, native["report"])
        self.connection.execute("INSERT INTO captures VALUES(?,?,?,?,?,?)",
                                (captured["id"], source["id"], captured["parent_id"], "PENDING", captured["created_at"], canonical(captured)))
        return self._capture_summary(captured)

    def register_source(self, payload, expected):
        name = text(payload.get("name"), "Source name", maximum=160)
        path = text(payload.get("path"), "Original source location", maximum=4096)
        kind = payload.get("kind", "sf36_ledger")
        if kind not in ("sf36_ledger", "mcp_quote", "governed_mcp"):
            raise Problem("SOURCE_KIND", "Choose an original SF36 ledger, MCP quote workspace or governed MCP descriptor")
        provenance = text(payload.get("provenance", ""), "Source provenance", maximum=6000, optional=True)
        native = capture_source(path, kind, self.node_executable)
        def operation():
            context = self._context(payload.get("data_context", "operational"), commit=True)
            if any(s["path"] == native["path"] or s["identity"] == native["identity"] for s in self._bodies("sources")):
                raise Problem("SOURCE_ALREADY_REGISTERED", "This original source is already registered; refresh or rebind that source", 409)
            source = {"id": identifier("source"), "name": name, "kind": kind, "path": native["path"], "identity": native["identity"],
                      "provenance": provenance, "data_context": context, "created_at": now(), "current_capture": None}
            self._put("sources", source)
            return {"id": source["id"], "source": source, "capture": self._new_capture(source, native)}
        return self._change(expected, "source.register", operation)

    def capture(self, ident, expected):
        with self.lock:
            source = self._get("sources", ident)
            if source.get("immutable_intake"):
                raise Problem("REFUND_INTAKE_REQUIRED", "Import the original successor refund packet in Credits; retained customer packets are immutable", 409)
        native = capture_source(source["path"], source.get("kind", "sf36_ledger"), self.node_executable)
        return self._change(expected, "source.capture", lambda: self._new_capture(self._get("sources", ident), native))

    def rebind(self, ident, payload, expected):
        path = text(payload.get("path"), "Original source location", maximum=4096)
        reason = text(payload.get("reason"), "Rebinding reason", maximum=3000)
        operator = text(payload.get("operator"), "Source owner", maximum=240)
        with self.lock:
            source = self._get("sources", ident)
            if source.get("immutable_intake"):
                raise Problem("REFUND_INTAKE_REQUIRED", "Use Credits to import the exact successor customer packet; the retained purchase identity stays fixed", 409)
            kind = source.get("kind", "sf36_ledger")
        native = capture_source(path, kind, self.node_executable)
        def operation():
            source = self._get("sources", ident)
            if any(s["id"] != ident and (s["path"] == native["path"] or s["identity"] == native["identity"]) for s in self._bodies("sources")):
                raise Problem("SOURCE_ALREADY_REGISTERED", "This path belongs to another registered source", 409)
            if source.get("current_capture"):
                before = self._get("captures", source["current_capture"])["report"]["rows"]
                after = {r["request_id"]: r for r in native["report"]["rows"]}
                if any(r["request_id"] not in after or after[r["request_id"]]["request_digest"] != r["request_digest"] for r in before):
                    raise Problem("LEDGER_CONTINUITY", "This source does not retain the registered original request identities; register a distinct source instead", 409)
            reattachment = {"from": source["path"], "to": native["path"], "reason": reason,
                            "operator": operator, "at": now(), "source_id": ident,
                            "from_capture": source.get("current_capture")}
            source.update(path=native["path"], identity=native["identity"])
            captured = self._new_capture(source, native, reattachment=reattachment)
            source["rebindings"] = source.get("rebindings", []) + [reattachment | {"to_capture": captured["id"]}]
            self._put("sources", source)
            return {"id": ident, "capture": captured}
        return self._change(expected, "source.rebind", operation)

    @staticmethod
    def _capture_summary(captured):
        return {k: captured.get(k) for k in ("id", "source_id", "parent_id", "status", "created_at", "reviewed_at", "operator", "reason")} | {
            "source": captured["report"]["source"], "captured_at": captured["report"]["captured_at"], "change_count": len(captured["changes"]),
            "change_counts": {kind: sum(c["kind"] == kind for c in captured["changes"]) for kind in ("ADDED", "CHANGED", "ABSENT")}}

    def captures(self, source_id, offset=0, limit=20):
        with self.lock:
            values = [self._capture_summary(json.loads(r[0])) for r in self.connection.execute(
                "SELECT body FROM captures WHERE source_id=? ORDER BY created_at DESC,id DESC", (source_id,))]
            return page(values, offset, limit)

    def inspect_capture(self, ident, offset=0, limit=20):
        with self.lock:
            saved = self._get("captures", ident)
            return self._capture_summary(saved) | {"changes": page(saved["changes"], offset, limit), "portfolio": saved["report"]["portfolio"]}

    def capture_original(self, ident):
        with self.lock:
            return self._get("captures", ident)

    def _accept_capture(self, captured, source):
        """Apply a reviewed source edition inside the original mutation transaction."""
        if captured["parent_id"] != source.get("current_capture"):
            raise Problem("SOURCE_CHANGED", "A different source edition was accepted; capture again against that edition", 409)
        self.connection.execute("UPDATE items SET missing=1 WHERE source_id=?", (source["id"],))
        for row in captured["report"]["rows"]:
            key = row_key(source["id"], row["request_id"])
            self.connection.execute("INSERT INTO items VALUES(?,?,?,?,0,?) ON CONFLICT(id) DO UPDATE SET capture_id=excluded.capture_id,missing=0,body=excluded.body",
                                    (key, source["id"], row["request_id"], captured["id"], canonical(row)))
        source["current_capture"] = captured["id"]
        self._put("sources", source)

    def decide_capture(self, ident, payload, expected):
        decision = payload.get("decision")
        if decision not in ("ACCEPT", "REJECT"):
            raise Problem("CAPTURE_DECISION", "Accept the original capture or reject it with a reason")
        operator = text(payload.get("operator"), "Source reviewer", maximum=240)
        reason = text(payload.get("reason"), "Source review reason", maximum=3000)
        def operation():
            captured = self._get("captures", ident)
            source = self._get("sources", captured["source_id"])
            if captured["status"] != "PENDING":
                raise Problem("CAPTURE_REVIEWED", "This source edition already has a retained decision", 409)
            if decision == "ACCEPT":
                self._accept_capture(captured, source)
            captured.update(status="ACCEPTED" if decision == "ACCEPT" else "REJECTED", operator=operator, reason=reason, reviewed_at=now())
            self.connection.execute("UPDATE captures SET status=?,body=? WHERE id=?", (captured["status"], canonical(captured), ident))
            return self._capture_summary(captured)
        return self._change(expected, "source." + decision.lower(), operation)

    def save_center(self, payload, expected):
        def operation():
            ident = payload.get("id") or identifier("center")
            previous = self._get("centers", ident) if payload.get("id") else None
            code = text(payload.get("code"), "Cost center code", maximum=100)
            if any(c["id"] != ident and c["code"] == code for c in self._bodies("centers")):
                raise Problem("COST_CENTER_CODE", "Use a distinct cost-center code", 409)
            if type(payload.get("active", True)) is not bool:
                raise Problem("COST_CENTER_STATE", "Active must be true or false")
            body = {"id": ident, "code": code, "name": text(payload.get("name"), "Cost center name", maximum=200),
                    "active": payload.get("active", True), "created_at": previous["created_at"] if previous else now(), "updated_at": now()}
            self._put("centers", body)
            return body
        return self._change(expected, "center.save", operation)

    def save_labels(self, payload, expected):
        try:
            values = list(parse_labels({"assets": payload.get("assets")}).values())
        except (ValueError, TypeError) as exc:
            raise Problem("INVALID_LABELS", str(exc)) from exc
        return self._change(expected, "labels.save", lambda: self._set_labels(values))

    def _set_labels(self, values):
        self.connection.execute("UPDATE meta SET value=? WHERE key='labels'", (canonical(values),))
        return {"assets": values}

    def save_period(self, payload, expected):
        def operation():
            ident = payload.get("id") or identifier("period")
            previous = self._get("periods", ident) if payload.get("id") else None
            if previous and previous["state"] == "CLOSED":
                raise Problem("PERIOD_CLOSED", "Reopen the original period before changing it", 409)
            start, end = day(payload.get("from_day")), day(payload.get("through_day"))
            if start > end:
                raise Problem("PERIOD_DATES", "The first recognition date must be on or before the last")
            if any(p["id"] != ident and start <= p["through_day"] and end >= p["from_day"] for p in self._bodies("periods")):
                raise Problem("PERIOD_OVERLAP", "Expense periods cannot overlap; each recognition date belongs to one period", 409)
            body = dict(previous or {"id": ident, "state": "OPEN", "generation": 0, "latest_close": None, "created_at": now()})
            body.update(name=text(payload.get("name"), "Period name", maximum=200), from_day=start, through_day=end, updated_at=now())
            self._put("periods", body)
            return body
        return self._change(expected, "period.save", operation)

    def save_coding(self, ident, payload, expected):
        def operation():
            item = self.item(ident)
            centers = {c["id"]: c for c in self._bodies("centers")}
            coding = validate_coding(item, payload, centers)
            dates = [coding["recognition_date"]]
            if item.get("coding"):
                dates.append(item["coding"]["recognition_date"])
            if any(p["state"] == "CLOSED" and any(p["from_day"] <= d <= p["through_day"] for d in dates) for p in self._bodies("periods")):
                raise Problem("PERIOD_CLOSED", "Reopen the affected original period before changing an issued expense", 409)
            coding.update(id=identifier("coding"), created_at=now(), previous=item["coding"]["id"] if item.get("coding") else None)
            self.connection.execute("INSERT INTO codings VALUES(?,?,?,?)", (coding["id"], ident, coding["created_at"], canonical(coding)))
            self.connection.execute("INSERT INTO coding_heads VALUES(?,?) ON CONFLICT(item_id) DO UPDATE SET coding_id=excluded.coding_id", (ident, coding["id"]))
            return coding
        return self._change(expected, "expense.code", operation)

    def _dispositions(self, period_id):
        return [json.loads(r[0]) for r in self.connection.execute(
            "SELECT d.body FROM disposition_heads h JOIN dispositions d ON d.id=h.disposition_id WHERE h.period_id=? ORDER BY h.item_id,h.code", (period_id,))]

    def _issued_reservation_lineage(self, issued_charges):
        """Join physical restore identities only through accepted original sources.

        Physical changes require the named reattachment between the exact
        accepted captures. UUIDs shared by unrelated sources establish no lineage.
        Current exposure remains attached to the actually observed ledger.
        """
        targets = {(entry["spending_reservation"]["request_id"], entry["spending_reservation"]["request_digest"])
                   for entry in issued_charges if entry.get("spending_reservation")}
        if not targets:
            return issued_charges
        parents, witnesses, transitions = {}, {}, []

        def root(key):
            parents.setdefault(key, key)
            while parents[key] != key:
                parents[key] = parents[parents[key]]
                key = parents[key]
            return key

        def connect(keys):
            if not keys:
                return
            anchor = root(keys[0])
            for key in keys[1:]:
                parents[root(key)] = anchor

        for source in self._bodies("sources"):
            kind = source.get("kind", "sf36_ledger")
            if kind not in ("sf36_ledger", "governed_mcp") or not source.get("current_capture"):
                continue
            active, histories, seen = set(targets), {}, set()
            newer_capture = None
            capture_id = source["current_capture"]
            while capture_id and active:
                if capture_id in seen:
                    raise Problem("SOURCE_CAPTURE_HISTORY", "The retained original source ancestry repeats a capture", 409)
                seen.add(capture_id)
                captured = self._get("captures", capture_id)
                if captured.get("source_id") != source["id"] or captured.get("status") != "ACCEPTED":
                    raise Problem("SOURCE_CAPTURE_HISTORY", "Use the original accepted source ancestry", 409)
                original_rows = {row["request_id"]: row for row in captured["report"]["rows"]}
                ledger = (captured["identity"] if kind == "sf36_ledger" else
                          captured["report"]["source"].get("reservation_ledger_identity"))
                for request_id, request_digest in tuple(active):
                    row = original_rows.get(request_id)
                    identity = spending_reservation_identity(ledger, request_id, request_digest)
                    if (row is None or row.get("request_digest") != request_digest or identity is None or
                            (kind == "governed_mcp" and row.get("native_detail", {}).get("spending_link") != "ORIGINAL_SF36")):
                        active.remove((request_id, request_digest))
                        continue
                    key = digest(identity)
                    history = histories.setdefault((request_id, request_digest), [])
                    if history and key != history[-1]:
                        reattachment = (newer_capture or {}).get("reattachment", {})
                        if (reattachment.get("source_id") != source["id"] or
                                reattachment.get("from_capture") != capture_id or
                                reattachment.get("to_capture") != newer_capture["id"] or
                                not reattachment.get("operator") or not reattachment.get("reason")):
                            active.remove((request_id, request_digest))
                            continue
                        transitions.append({"keys": [history[-1], key],
                            "reattachment": reattachment, "request_id": request_id, "request_digest": request_digest})
                    history.append(key)
                    witnesses.setdefault(key, {}).setdefault(source["id"], {
                        "identity": identity, "source_id": source["id"], "capture_id": capture_id})
                newer_capture = captured
                capture_id = captured.get("parent_id")
            for keys in histories.values():
                connect(keys)
        groups = {}
        for key, observations in witnesses.items():
            groups.setdefault(root(key), []).extend(observations.values())
        result = []
        for entry in issued_charges:
            identity = entry.get("spending_reservation")
            key = digest(identity) if identity else None
            history = groups.get(root(key), []) if key in parents else []
            if len({digest(value["identity"]) for value in history}) > 1:
                result.append(entry | {"spending_reservation_history": sorted(
                    history, key=lambda value: (digest(value["identity"]), value["source_id"], value["capture_id"])),
                    "spending_source_reattachments": sorted(
                        [edge["reattachment"] for edge in transitions if root(edge["keys"][0]) == root(key)],
                        key=lambda value: (value["source_id"], value["from_capture"], value["to_capture"]))})
            else:
                result.append(entry)
        return result

    def report(self, ident):
        with self.lock:
            period = self._get("periods", ident)
            closed_transfers = []
            for other in self._bodies("periods"):
                if other["id"] == ident or other["state"] != "CLOSED" or not other.get("latest_close"):
                    continue
                issued = self._get("closes", other["latest_close"])
                seen = set()
                captured_sources = {value["id"]: value for value in issued.get("native_captures", [])}
                for line in issued.get("allocations", []):
                    transfer = (line.get("native_payment") or {}).get("transfer_identity")
                    retained = line.get("original_spending_reservation") or {}
                    reservation = (spending_reservation_identity(retained.get("ledger"), line["request_id"], line["request_digest"])
                                   if retained.get("request_id") == line["request_id"] and
                                   retained.get("request_digest") == line["request_digest"] else None)
                    if reservation is None and line.get("source_kind", "sf36_ledger") in ("sf36_ledger", "governed_mcp"):
                        # Older issued ledger lines predate the additive identity
                        # field. Derive it from their own frozen accepted capture,
                        # never from the source's later locator or current ledger.
                        captured = captured_sources.get(line["source_capture"])
                        if captured and captured.get("source_id") == line["source_id"]:
                            original = next((row for row in captured.get("report", {}).get("rows", [])
                                if row.get("request_id") == line["request_id"] and row.get("request_digest") == line["request_digest"] and
                                row.get("state") == "settled" and row.get("settled_base_units") == line["settled_actual"]), None)
                            if original:
                                ledger = (captured["identity"] if line.get("source_kind", "sf36_ledger") == "sf36_ledger" else
                                          captured["report"]["source"].get("reservation_ledger_identity"))
                                reservation = spending_reservation_identity(ledger, line["request_id"], line["request_digest"])
                    key = (transfer, digest(reservation) if reservation else None, line["item_id"])
                    if (transfer or reservation) and key not in seen:
                        seen.add(key)
                        closed_transfers.append({"transfer_identity":transfer, "spending_reservation":reservation,
                            "period_id":other["id"], "period_name":other["name"], "close_id":issued["id"], "item_id":line["item_id"],
                            "source_capture":line["source_capture"], "recognition_date":line["recognition_date"]})
            closed_transfers = self._issued_reservation_lineage(closed_transfers)
            view = period_view(period, self._items(), self._source_views(), {c["id"]: c for c in self._bodies("centers")},
                               self._dispositions(ident), closed_transfers)
            view = self._credit_period(view)
            labels = json.loads(self.connection.execute("SELECT value FROM meta WHERE key='labels'").fetchone()[0])
            view["labels"] = labels
            view["context_sha256"] = digest([view["context_sha256"], labels])
            return view

    def dispose(self, period_id, payload, expected):
        def operation():
            period = self._get("periods", period_id)
            if period["state"] == "CLOSED":
                raise Problem("PERIOD_CLOSED", "Reopen the period before changing its exception decisions", 409)
            current = self.report(period_id)
            issue = next((x for x in current["issues"] if x["item_id"] == payload.get("item_id") and x["code"] == payload.get("code")), None)
            if issue is None or issue["basis"] != payload.get("basis"):
                raise Problem("ISSUE_CHANGED", "The source exception changed; review its current detail", 409)
            kind = payload.get("kind")
            if kind not in issue["allowed_kinds"]:
                raise Problem("ISSUE_ACTION", "Use the original source review or one of this issue's displayed dispositions")
            value = {"id": identifier("disposition"), "period_id": period_id, "item_id": issue["item_id"], "code": issue["code"],
                     "basis": issue["basis"], "kind": kind, "reason": text(payload.get("reason"), "Disposition reason", maximum=4000),
                     "operator": text(payload.get("operator"), "Disposition owner", maximum=240), "created_at": now()}
            self.connection.execute("INSERT INTO dispositions VALUES(?,?,?,?,?,?)",
                                    (value["id"], period_id, value["item_id"], value["code"], value["created_at"], canonical(value)))
            self.connection.execute("INSERT INTO disposition_heads VALUES(?,?,?,?) ON CONFLICT(period_id,item_id,code) DO UPDATE SET disposition_id=excluded.disposition_id",
                                    (period_id, value["item_id"], value["code"], value["id"]))
            return value
        return self._change(expected, "period.disposition", operation)

    def review(self, ident, payload, expected):
        def operation():
            report = self.report(ident)
            if report["period"]["state"] != "OPEN":
                raise Problem("PERIOD_CLOSED", "This period already has an issued edition", 409)
            value = {"id": identifier("review"), "period_id": ident, "created_at": now(), "context_sha256": report["context_sha256"],
                     "reviewer": text(payload.get("reviewer"), "Review owner", maximum=240),
                     "role": text(payload.get("role"), "Review capacity", maximum=240),
                     "notes": text(payload.get("notes"), "Review conclusion", maximum=6000),
                     "decision": "READY" if report["ready"] else "REQUIRES_CORRECTION", "snapshot": report}
            self.connection.execute("INSERT INTO reviews VALUES(?,?,?,?)", (value["id"], ident, value["created_at"], canonical(value)))
            return value
        return self._change(expected, "period.review", operation)

    def close_period(self, ident, payload, expected):
        def operation():
            period = self._get("periods", ident)
            review = self._get("reviews", payload.get("review_id"))
            if review["period_id"] != ident:
                raise Problem("REVIEW_PERIOD", "Use a review of this exact period")
            if period["state"] == "CLOSED":
                saved = self._get("closes", period["latest_close"])
                if saved["review"]["id"] == review["id"]:
                    return saved | {"already_closed": True}
                raise Problem("PERIOD_CLOSED", "The original period is already closed", 409)
            report = self.report(ident)
            if review["context_sha256"] != report["context_sha256"]:
                raise Problem("REVIEW_STALE", "Source, coding, or exception decisions changed after review; review their current state", 409)
            if review["decision"] != "READY" or not report["ready"]:
                raise Problem("PERIOD_EXCEPTIONS", "Complete the displayed exception decisions before issuing this period", 409)
            sequence = self.connection.execute("SELECT COALESCE(MAX(sequence),0)+1 FROM closes WHERE period_id=?", (ident,)).fetchone()[0]
            capture_ids = {s["current_capture"] for s in self._bodies("sources") if s.get("current_capture")}
            for rows in (report["allocations"], report["outstanding_reservations"], report["issues"]):
                capture_ids.update(r["source_capture"] for r in rows if r.get("source_capture"))
            value = dict(report)
            value.update(id=identifier("close"), status="CLOSED", sequence=sequence, created_at=now(),
                         previous=period.get("latest_close"), review={k: review[k] for k in ("id", "created_at", "reviewer", "role", "notes", "decision")},
                         native_captures=[self._get("captures", capture_id) for capture_id in sorted(capture_ids)],
                         refund_packets=self._issued_refund_packets(report),
                         labels=json.loads(self.connection.execute("SELECT value FROM meta WHERE key='labels'").fetchone()[0]))
            value["period"] = period | {"state": "CLOSED", "latest_close": value["id"]}
            self.connection.execute("INSERT INTO closes VALUES(?,?,?,?,?)", (value["id"], ident, sequence, value["created_at"], canonical(value)))
            period.update(state="CLOSED", latest_close=value["id"], updated_at=now())
            self._put("periods", period)
            return {"id": value["id"], "sequence": sequence, "period": period, "context_sha256": report["context_sha256"]}
        return self._change(expected, "period.close", operation)

    def reopen(self, ident, payload, expected):
        def operation():
            period = self._get("periods", ident)
            if period["state"] != "CLOSED":
                raise Problem("PERIOD_OPEN", "This period is already open", 409)
            entry = {"at": now(), "operator": text(payload.get("operator"), "Reopening owner", maximum=240),
                     "reason": text(payload.get("reason"), "Reopening reason", maximum=4000), "prior_close": period["latest_close"]}
            period.update(state="OPEN", generation=period["generation"] + 1, updated_at=now(),
                          reopenings=period.get("reopenings", []) + [entry])
            self._put("periods", period)
            return period
        return self._change(expected, "period.reopen", operation)

    def history(self, period_id, offset=0, limit=20):
        with self.lock:
            values = []
            for table, kind in (("reviews", "review"), ("closes", "close")):
                for value in self.connection.execute("SELECT body FROM " + table + " WHERE period_id=? ORDER BY created_at DESC,id DESC", (period_id,)):
                    body = json.loads(value[0])
                    values.append({k: body.get(k) for k in ("id", "created_at", "sequence", "decision", "context_sha256")} |
                                  {"kind": kind, "reviewer": body.get("reviewer") or body.get("review", {}).get("reviewer")})
            return page(sorted(values, key=lambda x: (x["created_at"], x["id"]), reverse=True), offset, limit)

    def issued(self, ident):
        with self.lock:
            return self._get("closes", ident)

    def saved_review(self, ident):
        with self.lock:
            return self._get("reviews", ident)

    def events(self, offset=0, limit=50):
        with self.lock:
            if type(offset) is not int or offset < 0 or type(limit) is not int or not 1 <= limit <= 200:
                raise Problem("INVALID_PAGE", "Invalid activity page")
            total = self.connection.execute("SELECT COUNT(*) FROM events").fetchone()[0]
            rows = [dict(x) for x in self.connection.execute("SELECT * FROM events ORDER BY sequence DESC LIMIT ? OFFSET ?", (limit, offset))]
            for row in rows:
                row["detail"] = json.loads(row.pop("body"))
            return {"items": rows, "total": total, "offset": offset, "next": offset + limit if offset + limit < total else None}

    def backup_to(self, destination):
        with self.lock:
            if self.closed:
                raise Problem("WORKSPACE_CLOSED", "The workspace is closed", 503)
            fd = os.open(destination, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
            os.close(fd)
            target = sqlite3.connect(destination)
            try:
                self.connection.backup(target)
            finally:
                target.close()
            private_file(Path(destination))

"""Non-custodial x402 buyer budget authorization and settlement receipt ledger.

Python 3.10+ standard library, SQLite WAL. No blockchain RPC, signer, wallet,
transaction, or money movement. Buyer-side offchain policy only; deploying agents
must not have keys able to issue consents or settlement attestations.
"""
from __future__ import annotations

import base64
import hashlib
import hmac
import ipaddress
import json
import re
import sqlite3
from datetime import datetime, timezone
from pathlib import Path
from typing import Any
from urllib.parse import urlsplit

SCHEMA="stellar-spend-governor/v1"
MAX_AMOUNT=2**63-1
# Same native request ceiling as sf31-buyer-client/request-body.mjs.
# The governor binds length and digest; it does not load request bodies.
MAX_REQUEST_BODY_BYTES=16*1024*1024
ID_PATTERN=re.compile(r"^[A-Za-z0-9._:-]{1,160}$")
NETWORKS={"stellar:testnet", "stellar:pubnet"}
CURRENCY_FIELDS=("max_single", "max_total", "max_per_utc_day", "max_per_actor_utc_day", "max_per_service_utc_day")
# Consent must identify the same purchase the x402 signer is about to authorize.
# Reject unknown fields instead of silently dropping e.g. a caller-provided payTo.
REQUEST_FIELDS=("request_id", "actor", "service", "network", "asset", "scheme", "max_amount", "resource",
                "pay_to", "max_timeout_seconds", "method", "body_present", "body_bytes",
                "body_sha256", "accepted_terms_sha256")
HTTP_METHODS={"GET", "HEAD", "POST", "PUT", "PATCH", "DELETE"}
EMPTY_BODY_SHA256=hashlib.sha256(b'').hexdigest()
CONSENT_KIND='owner-consent/complete-intent-v2'
RESUME_CONSENT_KIND='owner-consent/resume-expired-v1'

class Denied(ValueError):
    """Decision is DENIED: safely do not create or submit a payment."""


def canonical(value: Any)->bytes:
    return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True).encode('ascii')


def parse_amount(value: Any, label="amount") -> int:
    # Force integer base-unit strings. JS floats / Python float / JSON numeric values are forbidden.
    if not isinstance(value,str) or not re.fullmatch(r"0|[1-9][0-9]*",value):
        raise Denied(f"{label} must be a canonical nonnegative integer BASE-UNIT STRING")
    if len(value)>19:raise Denied(f"{label} beyond supported signed 64-bit base unit ceiling")
    num=int(value)
    if num>MAX_AMOUNT:raise Denied(f"{label} beyond supported signed 64-bit base unit ceiling")
    return num


def as_time(s: str)->datetime:
    if not isinstance(s,str):raise Denied('timestamp is not a string')
    try:t=datetime.fromisoformat(s.replace('Z','+00:00'))
    except (ValueError,TypeError):raise Denied('timestamp must be ISO-8601 UTC')
    if t.tzinfo is None or t.utcoffset().total_seconds()!=0:raise Denied('timestamp must be explicitly UTC')
    return t


def now_utc()->datetime:return datetime.now(timezone.utc)


def require_resource_url(value: Any)->str:
    """Reject ambiguous/unparsable purchase origins before issuing owner consent.

    Preserve the exact URL for HMAC binding. DNS resolution, redirects, challenge
    matching and signer equivalence remain the original client/operator's work.
    """
    if not isinstance(value,str) or not (9<=len(value)<=2048) or not value.startswith('https://'):
        raise Denied('resource must be a bounded HTTPS URL with a host')
    if any(ord(c)<33 or ord(c)>126 for c in value) or '\\' in value or '#' in value:
        raise Denied('resource contains unsafe URL bytes or a fragment')
    try:
        parsed=urlsplit(value)
        host=parsed.hostname
        port=parsed.port
    except ValueError as exc:
        raise Denied('resource has an invalid HTTPS authority') from exc
    if parsed.scheme!='https' or not parsed.netloc or not host or '@' in parsed.netloc or port==0:
        raise Denied('resource has an invalid HTTPS authority')
    labels=host.split('.')
    legacy_ip=all(re.fullmatch(r'(?:0x[0-9a-f]+|[0-9]+)',label) for label in labels)
    if (len(host)>253 or len(labels)<2 or legacy_ip or
        host in {'localhost','local','localdomain','internal','home.arpa','ip6-localhost','ip6-loopback'} or
        any(host.endswith(x) for x in ('.localhost','.local','.localdomain','.internal','.home.arpa')) or
        not all(re.fullmatch(r'[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?',label) for label in labels)):
        raise Denied('resource has an unsafe or non-DNS host')
    try:
        ipaddress.ip_address(host)
    except ValueError:
        pass
    else:
        raise Denied('resource address literal not allowed')
    return value


def validate_request(obj:dict[str,Any])->dict[str,Any]:
    if not isinstance(obj,dict) or set(obj)!=set(REQUEST_FIELDS):
        raise Denied('canonical buyer purchase intent fields mismatch')
    r={k:obj[k] for k in REQUEST_FIELDS}
    for k in ("request_id","actor","service"):
        if not isinstance(r[k],str) or not ID_PATTERN.fullmatch(r[k]):raise Denied(f'invalid {k}')
    if r['network'] not in NETWORKS:raise Denied('unsupported Stellar network')
    if not isinstance(r['asset'],str) or not re.fullmatch(r'[A-Z2-7]{56}',r['asset']):
        raise Denied('asset must be Soroban SEP-41 contract identifier, not classic asset alias')
    if r['scheme'] not in ('exact','upto'):raise Denied('unsupported payment scheme')
    require_resource_url(r['resource'])
    if parse_amount(r['max_amount'],'max_amount')<1:raise Denied('max_amount must be positive')
    # A resource URL and amount alone do not identify a payment: recipient,
    # expiry, HTTP operation, body and accepted x402 requirement must bind too.
    payee=r['pay_to']
    if not isinstance(payee,str) or not (1<=len(payee)<=256) or payee!=payee.strip() or any(ord(c)<33 or ord(c)>126 for c in payee):
        raise Denied('pay_to must be a bounded nonempty printable payment recipient')
    timeout=r['max_timeout_seconds']
    if type(timeout) is not int or not (1<=timeout<=86400):
        raise Denied('max_timeout_seconds must be an integer in 1..86400')
    if not isinstance(r['method'],str) or r['method'] not in HTTP_METHODS:
        raise Denied('method must be an uppercase supported HTTP verb')
    present=r['body_present'];size=r['body_bytes']
    if type(present) is not bool or type(size) is not int or not (0<=size<=MAX_REQUEST_BODY_BYTES):
        raise Denied('body presence/byte length invalid')
    if (not present) and size!=0:
        raise Denied('body absent but byte length is nonzero')
    for field in ('body_sha256','accepted_terms_sha256'):
        if not isinstance(r[field],str) or not re.fullmatch(r'[0-9a-f]{64}',r[field]):
            raise Denied(field+' must be lowercase SHA-256 hex')
    if not present and r['body_sha256']!=EMPTY_BODY_SHA256:
        raise Denied('absent body must have the SHA-256 of empty bytes')
    if r['method'] in ('GET','HEAD') and present:
        raise Denied('GET/HEAD cannot carry a request body')
    return r


def validate_policy(policy:dict[str,Any])->dict[tuple[str,str],dict[str,int]]:
    if not isinstance(policy,dict) or policy.get('schema')!=SCHEMA or not isinstance(policy.get('assets'),list):
        raise Denied('incorrect policy schema/assets')
    result={}
    for item in policy['assets']:
        pair=(item.get('network'),item.get('asset'))
        if pair[0] not in NETWORKS or not isinstance(pair[1],str) or not re.fullmatch(r'[A-Z2-7]{56}',pair[1]):
            raise Denied('invalid network/asset in policy')
        if pair in result:raise Denied('duplicate asset policy')
        limits={key:parse_amount(item.get(key),key) for key in CURRENCY_FIELDS}
        if any(v==0 for v in limits.values()):raise Denied('limits must be positive')
        result[pair]=limits
    if not result:raise Denied('empty asset allowlist')
    return result


def secret(key:bytes,name:str)->bytes:
    if not isinstance(key,bytes) or len(key)<32:raise Denied(f'{name} must be at least 32 random bytes, kept outside caller/DB')
    return key


def token_for(key:bytes,claims:dict[str,Any])->str:
    payload=base64.urlsafe_b64encode(canonical(claims)).rstrip(b'=')
    sig=hmac.new(key,payload,hashlib.sha256).digest()
    return payload.decode('ascii')+'.'+base64.urlsafe_b64encode(sig).rstrip(b'=').decode('ascii')


def token_claims(key:bytes,value:str)->dict[str,Any]:
    if not isinstance(value,str) or len(value)>8192:raise Denied("authorization token invalid or oversize")
    try:
        a,b=value.split('.')
        data=a.encode('ascii')
        candidate=base64.urlsafe_b64decode(b+'='*(-len(b)%4))
        expected=hmac.new(key,data,hashlib.sha256).digest()
        if not hmac.compare_digest(expected,candidate):raise ValueError('bad mac')
        raw=base64.urlsafe_b64decode(a+'='*(-len(a)%4))
        claims=json.loads(raw)
        if canonical(claims)!=raw:raise ValueError('noncanonical claims')
        if not isinstance(claims,dict):raise ValueError('object required')
        return claims
    except (AttributeError,TypeError,UnicodeError,ValueError,json.JSONDecodeError) as e:
        raise Denied('authorization signature or encoding invalid') from e


def issue_consent(consent_key:bytes,request:dict,expiry_utc:str,*,resume_release_journal_mac:str|None=None)->str:
    """OPERATORS ONLY. One specific request, max amount, resource and short expiry."""
    r=validate_request(request)
    expiry=as_time(expiry_utc)
    if expiry<=now_utc():raise Denied('consent expiry must be in the future')
    if (expiry-now_utc()).total_seconds()>900:raise Denied('consent expires later than 15 minute safety window')
    claims={'kind':CONSENT_KIND,'request':r,'expires_at':expiry_utc}
    if resume_release_journal_mac is not None:
        _hash(resume_release_journal_mac,'resume release journal MAC')
        claims.update(kind=RESUME_CONSENT_KIND,release_journal_mac=resume_release_journal_mac)
    return token_for(secret(consent_key,'consent key'),claims)


def issue_finality_attestation(operator_key:bytes,reservation_id:str,actual_amount:str,receipt_ref:str,proof_sha256:str)->str:
    """PRIVILEGED RECEIPT WATCHER ONLY: signs its actual finalized network receipt."""
    if not isinstance(reservation_id,str) or not ID_PATTERN.fullmatch(reservation_id):raise Denied('invalid reservation id')
    parse_amount(actual_amount)
    if not isinstance(receipt_ref,str) or not receipt_ref.strip() or len(receipt_ref)>512:raise Denied('empty/oversize receipt ref')
    if not isinstance(proof_sha256,str) or not re.fullmatch('[0-9a-f]{64}',proof_sha256):raise Denied('invalid original provider receipt sha256')
    return token_for(secret(operator_key,'operator key'),{'kind':'finality-attestation','request_id':reservation_id,'actual_amount':actual_amount,'receipt_ref':receipt_ref,'proof_sha256':proof_sha256})


EXPIRY_ATTESTATION_KIND = 'expired-untransferred-authorization/v1'
EXPIRY_RESUME_KIND = 'resume-expired-authorization/v1'
EXPIRY_ATTESTATION_FIELDS = frozenset({
    'kind', 'request_id', 'request_digest', 'reservation_generation',
    'network', 'expiry_ledger', 'observed_ledger', 'proof_sha256',
})
EXPIRY_RESUME_FIELDS = frozenset({
    'kind', 'request_id', 'request_digest', 'release_journal_mac',
    'release_proof_sha256', 'expires_at',
})


def _hash(value, label):
    if not isinstance(value, str) or not re.fullmatch(r'[0-9a-f]{64}', value):
        raise Denied('invalid ' + label)
    return value


def _expiry_claim(claim):
    if type(claim) is not dict or set(claim) != EXPIRY_ATTESTATION_FIELDS or \
            claim.get('kind') != EXPIRY_ATTESTATION_KIND:
        raise Denied('wrong expired-authorization attestation')
    if not isinstance(claim['request_id'], str) or not ID_PATTERN.fullmatch(claim['request_id']):
        raise Denied('invalid expired-authorization reservation')
    for key in ('request_digest', 'reservation_generation', 'proof_sha256'):
        _hash(claim[key], key)
    if claim['network'] not in NETWORKS:
        raise Denied('invalid expired-authorization network')
    if type(claim['expiry_ledger']) is not int or not (1 <= claim['expiry_ledger'] < 2**32) or \
            type(claim['observed_ledger']) is not int or \
            not (claim['expiry_ledger'] < claim['observed_ledger'] < 2**32):
        raise Denied('later synchronized ledger must exceed authorization expiry')
    return claim


def issue_expired_authorization_attestation(operator_key: bytes, *, request_id: str,
        request_digest: str, reservation_generation: str, network: str,
        expiry_ledger: int, observed_ledger: int, proof_sha256: str) -> str:
    """Trusted observer only: bind proven expiry AND no transfer to one generation.

    The ledger does not infer nonpayment from time or an absent local receipt.
    The original source/chain observer must establish those facts before issuing.
    This is a release attestation, never a zero-value settlement receipt.
    """
    claim = _expiry_claim({'kind': EXPIRY_ATTESTATION_KIND, 'request_id': request_id,
        'request_digest': request_digest, 'reservation_generation': reservation_generation,
        'network': network, 'expiry_ledger': expiry_ledger,
        'observed_ledger': observed_ledger, 'proof_sha256': proof_sha256})
    return token_for(secret(operator_key, 'operator key'), claim)


class Governor:
    def __init__(self,db: str|Path,policy:dict,consent_key:bytes,audit_key:bytes,operator_key:bytes):
        self.limits=validate_policy(policy)
        self.ck=secret(consent_key,'consent key');self.ak=secret(audit_key,'audit key');self.ok=secret(operator_key,'operator key')
        # A memory-backed database loses every reserved maximum at process
        # exit. SQLite also silently declines WAL on unsupported databases,
        # returning the actual mode from PRAGMA journal_mode=WAL.
        db_path=str(db)
        if db_path==':memory:' or db_path.startswith('file:'):
            raise Denied('durable spend ledger requires an on-disk SQLite file path')
        self.db=sqlite3.connect(db_path,isolation_level=None,timeout=30)
        try:
            self.db.execute('PRAGMA busy_timeout=30000')
            actual_mode=self.db.execute('PRAGMA journal_mode=WAL').fetchone()[0]
            if actual_mode.lower()!='wal':
                raise Denied('durable spend ledger requires confirmed SQLite WAL mode')
            self.db.execute('PRAGMA synchronous=FULL')
            if self.db.execute('PRAGMA synchronous').fetchone()[0]!=2:
                raise Denied('durable spend ledger requires confirmed SQLite FULL sync')
        except BaseException:
            self.db.close()
            raise
        self.db.execute('''CREATE TABLE IF NOT EXISTS reservations (
            request_id TEXT PRIMARY KEY, request_digest TEXT NOT NULL,
            actor TEXT NOT NULL, service TEXT NOT NULL, network TEXT NOT NULL,
            asset TEXT NOT NULL, scheme TEXT NOT NULL, amount TEXT NOT NULL,
            day TEXT NOT NULL, state TEXT NOT NULL, actual TEXT NOT NULL,
            receipt_ref TEXT NOT NULL, proof_sha256 TEXT NOT NULL
        )''')
        self.db.execute('''CREATE TABLE IF NOT EXISTS journal (
            sequence INTEGER PRIMARY KEY AUTOINCREMENT, event TEXT NOT NULL,
            prior_mac TEXT NOT NULL, mac TEXT NOT NULL
        )''')

    def close(self)->None:self.db.close()

    def _append(self,evt:dict)->None:
        prior=self.db.execute('SELECT mac FROM journal ORDER BY sequence DESC LIMIT 1').fetchone()
        prior_mac=prior[0] if prior else '0'*64
        serialized=canonical(evt).decode('ascii')
        mac=hmac.new(self.ak,(prior_mac+'\n'+serialized).encode('ascii'),hashlib.sha256).hexdigest()
        self.db.execute('INSERT INTO journal(event,prior_mac,mac) VALUES(?,?,?)',(serialized,prior_mac,mac))

    def _audit(self)->dict[str,dict]:
        """Verify HMAC chain AND persisted reservation projection before each mutation."""
        prior='0'*64; ledger={}; generations={}; releases={}; seq_expect=1
        for seq,serialized,parent,mac in self.db.execute('SELECT sequence,event,prior_mac,mac FROM journal ORDER BY sequence'):
            if seq!=seq_expect or parent!=prior:raise Denied('journal sequence/parent integrity failure')
            calc=hmac.new(self.ak,(parent+'\n'+serialized).encode('ascii'),hashlib.sha256).hexdigest()
            if not hmac.compare_digest(calc,mac):raise Denied('journal HMAC integrity failure')
            evt=json.loads(serialized)
            if canonical(evt).decode('ascii')!=serialized:raise Denied('journal canonical mismatch')
            if evt['type']=='reserve':
                rr=evt['reservation'];rid=rr['request_id']
                if rid in ledger:raise Denied('duplicate reservation event')
                ledger[rid]=rr.copy()
                generations[rid]=mac
            elif evt['type']=='expire_untransferred':
                claim=_expiry_claim(evt['attestation'])
                rid=claim['request_id'];rr=ledger.get(rid)
                if rr is None or rr['state']!='reserved' or \
                        rr['request_digest']!=claim['request_digest'] or \
                        rr['network']!=claim['network'] or \
                        generations.get(rid)!=claim['reservation_generation']:
                    raise Denied('invalid expired-authorization release transition')
                rr.update(state='expired',actual='0',
                    receipt_ref='expired-authorization/'+claim['reservation_generation'],
                    proof_sha256=claim['proof_sha256'])
                releases[rid]=mac
            elif evt['type']=='resume_expired':
                rid=evt['request_id'];rr=ledger.get(rid)
                if rr is None or rr['state']!='expired' or \
                        rr['request_digest']!=evt['request_digest'] or \
                        releases.get(rid)!=evt['release_journal_mac'] or \
                        rr['proof_sha256']!=evt['release_proof_sha256']:
                    raise Denied('invalid expired-authorization resume transition')
                day=evt['day']
                if not isinstance(day,str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}',day):
                    raise Denied('invalid resumed reservation day')
                as_time(day+'T00:00:00+00:00')
                rr.update(day=day,state='reserved',actual='0',receipt_ref='',proof_sha256='')
                generations[rid]=mac
                releases.pop(rid,None)
            elif evt['type']=='finalize':
                rid=evt['request_id'];rr=ledger.get(rid)
                if rr is None or rr['state']!='reserved':raise Denied('invalid finalize transition')
                if parse_amount(evt['actual'])>parse_amount(rr['amount']):raise Denied('settled more than authorized')
                rr.update(state='settled',actual=evt['actual'],receipt_ref=evt['receipt_ref'],proof_sha256=evt['proof_sha256'])
            else:raise Denied('unknown journal event')
            prior=mac;seq_expect+=1
        cols=['request_id','request_digest','actor','service','network','asset','scheme','amount','day','state','actual','receipt_ref','proof_sha256']
        on_disk={tuple(row)[0]:dict(zip(cols,row)) for row in self.db.execute('SELECT '+','.join(cols)+' FROM reservations')}
        if ledger!=on_disk:raise Denied('ledger projection tamper/rollback mismatch')
        return ledger

    def audit(self)->dict:
        ledger=self._audit()
        return {'outcome':'JOURNAL_CONSISTENT','rows':len(ledger),'events':self.db.execute('SELECT COUNT(*) FROM journal').fetchone()[0],
                'warning':'HMAC source keys are external; whole-database rollback requires independent checkpoint/witness detection'}

    def reservation(self,request:dict)->dict:
        """Read one original reservation against its complete approved intent.

        A consistent SQLite read transaction covers journal and projection; no
        new reservation, consent, release or finality attestation is produced.
        """
        r=validate_request(request)
        digest=hashlib.sha256(canonical(r)).hexdigest()
        return self.reservation_by_digest(r['request_id'],digest)

    def reservation_by_digest(self,request_id:str,request_digest:str)->dict:
        """Authenticate a retained original reservation ID/digest without a preimage.

        This read does not establish omitted purchase terms or transaction
        association. A trusted recovery caller must separately bind its frozen
        operator inputs and independently verify the selected transfer.
        """
        if not isinstance(request_id,str) or not ID_PATTERN.fullmatch(request_id) or \
                not isinstance(request_digest,str) or not re.fullmatch('[0-9a-f]{64}',request_digest):
            raise Denied('invalid original reservation identity')
        self.db.execute('BEGIN')
        try:
            row=self._audit().get(request_id)
            if row is None:raise Denied('unknown reserved payment')
            if not hmac.compare_digest(row['request_digest'],request_digest):
                raise Denied('approved request differs from original reservation')
            self.db.execute('COMMIT')
            return row.copy()
        except BaseException:
            self.db.execute('ROLLBACK');raise


    def _authorization_events(self, request_id):
        """Read generation identities inside the caller's already audited transaction."""
        generation=release=None
        for serialized,mac in self.db.execute('SELECT event,mac FROM journal ORDER BY sequence'):
            event=json.loads(serialized);kind=event['type']
            if kind=='reserve' and event['reservation']['request_id']==request_id:
                generation=mac
            elif event.get('request_id')==request_id and kind=='resume_expired':
                generation=mac;release=None
            elif kind=='expire_untransferred' and event['attestation']['request_id']==request_id:
                release=mac
        return generation,release

    def authorization(self, request:dict)->dict:
        """Read the original audited row and its immutable authorization generation."""
        r=validate_request(request);digest=hashlib.sha256(canonical(r)).hexdigest()
        self.db.execute('BEGIN')
        try:
            row=self._audit().get(r['request_id'])
            if row is None or not hmac.compare_digest(row['request_digest'],digest):
                raise Denied('original reservation and approved request required')
            generation,release=self._authorization_events(r['request_id'])
            result={'reservation':row.copy(),'generation':generation,'release_journal_mac':release}
            self.db.execute('COMMIT')
            return result
        except BaseException:
            self.db.execute('ROLLBACK');raise

    def release_expired_authorization(self, attestation_token:str)->dict:
        """Release one expired, independently observed untransferred generation.

        Original source and chain verification belong to the trusted worker.
        A stopped process or elapsed wall clock alone cannot issue this transition.
        """
        claim=_expiry_claim(token_claims(self.ok,attestation_token))
        self.db.execute('BEGIN IMMEDIATE')
        try:
            row=self._audit().get(claim['request_id'])
            if row is None or row['request_digest']!=claim['request_digest'] or \
                    row['network']!=claim['network']:
                raise Denied('expired authorization does not bind original reservation')
            generation,release=self._authorization_events(claim['request_id'])
            if generation!=claim['reservation_generation']:
                raise Denied('expired authorization belongs to a different reservation generation')
            receipt='expired-authorization/'+generation
            if row['state']=='expired':
                if row['actual']!='0' or row['proof_sha256']!=claim['proof_sha256'] or \
                        row['receipt_ref']!=receipt:
                    raise Denied('expired-authorization release conflicts with original proof')
                self.db.execute('COMMIT')
                return {'outcome':'IDEMPOTENT_EXPIRED_RELEASE','request_id':claim['request_id'],
                    'request_sha256':claim['request_digest'],'generation':generation,
                    'proof_sha256':row['proof_sha256'],'release_journal_mac':release,
                    'released_atomic_units':row['amount'],'actual':'0','state':'expired'}
            if row['state']!='reserved':
                raise Denied('only the original reserved generation can expire')
            self.db.execute("UPDATE reservations SET state='expired',actual='0',receipt_ref=?,proof_sha256=? WHERE request_id=?",
                (receipt,claim['proof_sha256'],claim['request_id']))
            self._append({'type':'expire_untransferred','attestation':claim})
            _,release=self._authorization_events(claim['request_id'])
            self.db.execute('COMMIT')
            return {'outcome':'EXPIRED_AUTHORIZATION_RELEASED','request_id':claim['request_id'],
                'request_sha256':claim['request_digest'],'generation':generation,
                'proof_sha256':claim['proof_sha256'],'release_journal_mac':release,
                'released_atomic_units':row['amount'],'actual':'0','state':'expired'}
        except BaseException:
            self.db.execute('ROLLBACK');raise

    def issue_expired_resume_permit(self, request:dict, *, proof_sha256:str,
                                   expiry_utc:str)->str:
        """Privileged host only; fresh human consent is additionally required at reserve."""
        r=validate_request(request);proof=_hash(proof_sha256,'release proof')
        expiry=as_time(expiry_utc);now=now_utc()
        if not (0<(expiry-now).total_seconds()<=900):
            raise Denied('resume permit must expire within 15 minutes')
        current=self.authorization(r);row=current['reservation']
        if row['state']!='expired' or row['proof_sha256']!=proof or not current['release_journal_mac']:
            raise Denied('original authenticated expiry release required')
        return token_for(self.ok,{'kind':EXPIRY_RESUME_KIND,'request_id':r['request_id'],
            'request_digest':row['request_digest'],'release_journal_mac':current['release_journal_mac'],
            'release_proof_sha256':proof,'expires_at':expiry_utc})

    def _validate_expired_resume(self, token, request, digest, prior):
        claim=token_claims(self.ok,token)
        if set(claim)!=EXPIRY_RESUME_FIELDS or claim.get('kind')!=EXPIRY_RESUME_KIND or \
                claim.get('request_id')!=request['request_id'] or claim.get('request_digest')!=digest or \
                claim.get('release_proof_sha256')!=prior['proof_sha256']:
            raise Denied('resume permit does not bind the original expiry release')
        now=now_utc();expiry=as_time(claim.get('expires_at'))
        if not (0<(expiry-now).total_seconds()<=900):
            raise Denied('resume permit expired or exceeds its authorization window')
        _,release=self._authorization_events(request['request_id'])
        if not release or claim.get('release_journal_mac')!=release:
            raise Denied('resume permit belongs to another release generation')
        return claim

    def _budget(self,r:dict,day:str,ledger:dict)->dict:
        limits=self.limits.get((r['network'],r['asset']))
        if limits is None:raise Denied('asset/network not allowlisted by operator')
        other=[v for v in ledger.values() if v['network']==r['network'] and v['asset']==r['asset']]
        def amt(v):return parse_amount(v['amount']) if v['state']=='reserved' else parse_amount(v['actual'])
        spend={
         'max_single':0,
         'max_total':sum(map(amt,other)),
         'max_per_utc_day':sum(amt(x) for x in other if x['day']==day),
         'max_per_actor_utc_day':sum(amt(x) for x in other if x['day']==day and x['actor']==r['actor']),
         'max_per_service_utc_day':sum(amt(x) for x in other if x['day']==day and x['service']==r['service'])}
        amount=parse_amount(r['max_amount'])
        offenders=[k for k,prior in spend.items() if amount+prior>limits[k]]
        return {'approved':not offenders,'denied_by':offenders,'reserved_max_base_units':str(amount),'limit_remaining':{k:str(max(0,limits[k]-prior)) for k,prior in spend.items()}}

    def estimate(self,request:dict)->dict:
        r=validate_request(request)
        ledger=self._audit()
        return {**self._budget(r,now_utc().date().isoformat(),ledger),'note':'Read-only estimate is not a reservation; race requires atomic reserve.'}

    def reserve(self,request:dict,consent_token:str,*,resume_authorization_token:str|None=None)->dict:
        r=validate_request(request);day=now_utc().date().isoformat()
        claims=token_claims(self.ck,consent_token)
        if claims.get('kind') not in (CONSENT_KIND,RESUME_CONSENT_KIND) or claims.get('request')!=r:
            raise Denied('explicit owner consent does not bind exactly to this payment request')
        if as_time(claims.get('expires_at'))<=now_utc():raise Denied('explicit owner consent expired')
        digest=hashlib.sha256(canonical(r)).hexdigest()
        self.db.execute('BEGIN IMMEDIATE')
        try:
            ledger=self._audit()
            prior=ledger.get(r['request_id'])
            if prior is not None:
                if prior['request_digest']!=digest:raise Denied('request_id reused with different terms')
                if prior['state']=='expired' and resume_authorization_token is not None:
                    resume=self._validate_expired_resume(resume_authorization_token,r,digest,prior)
                    if claims.get('kind')!=RESUME_CONSENT_KIND or \
                            claims.get('release_journal_mac')!=resume['release_journal_mac']:
                        raise Denied('fresh consent must bind this exact expired-authorization release')
                    budget=self._budget(r,day,ledger)
                    if not budget['approved']:raise Denied('budget exceeded: '+','.join(budget['denied_by']))
                    self.db.execute("UPDATE reservations SET day=?,state='reserved',actual='0',receipt_ref='',proof_sha256='' WHERE request_id=?",
                        (day,r['request_id']))
                    self._append({'type':'resume_expired','request_id':r['request_id'],
                        'request_digest':digest,'release_journal_mac':resume['release_journal_mac'],
                        'release_proof_sha256':resume['release_proof_sha256'],'day':day})
                    self.db.execute('COMMIT')
                    return {'outcome':'RESERVED','request_id':r['request_id'],'max_amount':r['max_amount'],
                        'scheme':r['scheme'],'network':r['network'],'asset':r['asset'],
                        'audit_required':'RECONCILE_FINALITY','resumed_from':resume['release_journal_mac']}
                self.db.execute('COMMIT')
                return {'outcome':'IDEMPOTENT_EXISTING','state':prior['state'],'request_id':r['request_id'],
                        'max_amount':prior['amount'],'actual':prior['actual'],'receipt_ref':prior['receipt_ref']}
            if claims.get('kind')!=CONSENT_KIND:
                raise Denied('resumed consent requires its original expired reservation')
            budget=self._budget(r,day,ledger)
            if not budget['approved']:raise Denied('budget exceeded: '+','.join(budget['denied_by']))
            row={'request_id':r['request_id'],'request_digest':digest,'actor':r['actor'],'service':r['service'],
                 'network':r['network'],'asset':r['asset'],'scheme':r['scheme'],'amount':r['max_amount'],
                 'day':day,'state':'reserved','actual':'0','receipt_ref':'','proof_sha256':''}
            cols=list(row)
            self.db.execute(f"INSERT INTO reservations({','.join(cols)}) VALUES({','.join('?' for _ in cols)})",tuple(row.values()))
            self._append({'type':'reserve','reservation':row})
            self.db.execute('COMMIT')
            return {'outcome':'RESERVED','request_id':r['request_id'], 'max_amount':r['max_amount'], 'scheme':r['scheme'],
                    'network':r['network'],'asset':r['asset'], 'audit_required':'RECONCILE_FINALITY'}
        except BaseException:
            self.db.execute('ROLLBACK');raise

    def reconcile(self,attestation_token:str)->dict:
        """Call from trusted operator *after independently verifying actual chain finality*.
        Unused reservation capacity is released; a pending payment is NEVER auto-refunded.
        """
        claim=token_claims(self.ok,attestation_token)
        if claim.get('kind')!='finality-attestation':raise Denied('wrong attestation kind')
        rid=claim.get('request_id');actual=claim.get('actual_amount')
        if not isinstance(rid,str) or not ID_PATTERN.fullmatch(rid):raise Denied('invalid receipt reservation id')
        amount=parse_amount(actual);receipt=claim.get('receipt_ref');proof=claim.get('proof_sha256')
        if not isinstance(receipt,str) or not receipt or not isinstance(proof,str) or not re.fullmatch('[0-9a-f]{64}',proof):
            raise Denied('invalid receipt details')
        self.db.execute('BEGIN IMMEDIATE')
        try:
            ledger=self._audit();row=ledger.get(rid)
            if row is None:raise Denied('unknown reserved payment')
            if row['state']=='settled':
                if row['actual']==actual and row['receipt_ref']==receipt and row['proof_sha256']==proof:
                    self.db.execute('COMMIT');return {'outcome':'IDEMPOTENT_FINALIZED','request_id':rid,'actual':actual}
                raise Denied('finality conflict for already finalized reservation')
            if row['state']!='reserved':raise Denied('finality requires an active original reservation')
            if amount>parse_amount(row['amount']):raise Denied('actual settlement exceeds signed/reserved maximum')
            if row['scheme']=='exact' and amount!=parse_amount(row['amount']):raise Denied('exact scheme must settle the exact reserved amount')
            if any(x['state']=='settled' and x['network']==row['network'] and x['receipt_ref']==receipt and x['request_id']!=rid for x in ledger.values()):
                raise Denied('finalized network receipt already assigned to another request')
            self.db.execute("UPDATE reservations SET state='settled',actual=?,receipt_ref=?,proof_sha256=? WHERE request_id=?",
                            (actual,receipt,proof,rid))
            self._append({'type':'finalize','request_id':rid,'actual':actual,'receipt_ref':receipt,'proof_sha256':proof})
            self.db.execute('COMMIT')
            return {'outcome':'FINALIZED','request_id':rid,'actual':actual,'unspent_released':str(parse_amount(row['amount'])-amount),
                    'note':'Operator-attested result; ledger itself does not fetch or independently validate Stellar RPC.'}
        except BaseException:
            self.db.execute('ROLLBACK');raise

"""Read-only SF36 buyer statements. Python 3.10+, standard library only.

Run beside the existing governor.py. This module never constructs a Governor,
loads signing keys, mutates the ledger, or makes network requests.
"""
from __future__ import annotations

import argparse
import base64
import csv
import hashlib
import html
import io
import json
import os
import re
import sqlite3
import sys
from datetime import date, datetime, timezone
from pathlib import Path
from typing import Any

from governor import ID_PATTERN, NETWORKS, canonical, parse_amount, validate_policy

SCHEMA = 'stellar-buyer-statement/v1'
COLUMNS = ('request_id', 'request_digest', 'actor', 'service', 'network', 'asset',
           'scheme', 'amount', 'day', 'state', 'actual', 'receipt_ref', 'proof_sha256')
MONEY = ('settled_base_units', 'reserved_base_units', 'released_capacity_base_units')
CSV_FIELDS = ('request_id', 'day', 'actor', 'service', 'network', 'asset', 'scheme',
              'state', 'amount', *MONEY, 'age_utc_days', 'receipt_ref', 'proof_sha256')
HEX = re.compile(r'[0-9a-f]{64}')
ASSET = re.compile(r'[A-Z2-7]{56}')


class StatementError(ValueError):
    """The requested statement cannot be produced without misleading the operator."""


def utc_day(value: Any) -> str:
    if not isinstance(value, str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}', value):
        raise StatementError('day must be YYYY-MM-DD')
    try:
        date.fromisoformat(value)
    except ValueError as exc:
        raise StatementError('day is not a calendar date') from exc
    return value


def read_snapshot(database: str | Path) -> dict:
    """Read committed WAL data in ONE transaction, without creating a missing DB.

    Do not use immutable=1: it can omit the active WAL. SQLite may maintain WAL
    shared-memory sidecars; this command issues no data/schema/checkpoint writes.
    """
    path = Path(database).expanduser().resolve(strict=True)
    if not path.is_file():
        raise StatementError('database must be an existing SQLite file')
    con = sqlite3.connect(path.as_uri() + '?mode=ro', uri=True,
                          isolation_level=None, timeout=10)
    try:
        con.execute('PRAGMA query_only=ON')
        con.execute('PRAGMA trusted_schema=OFF')
        con.execute('BEGIN')
        # First SELECT fixes the snapshot, including all later metadata reads.
        kinds = dict(con.execute("SELECT name,type FROM sqlite_master WHERE name IN ('reservations','journal')"))
        if kinds != {'reservations': 'table', 'journal': 'table'}:
            raise StatementError('expected the existing SF36 reservations and journal tables')
        actual = {r[1] for r in con.execute('PRAGMA table_info(reservations)')}
        if not set(COLUMNS) <= actual:
            raise StatementError('SF36 reservations schema is missing required columns')
        rows = [dict(zip(COLUMNS, row)) for row in con.execute(
            'SELECT ' + ','.join(COLUMNS) + ' FROM reservations ORDER BY day,request_id')]
        events, sequence = con.execute('SELECT COUNT(*),COALESCE(MAX(sequence),0) FROM journal').fetchone()
        result = {'rows': rows, 'journal_events': events, 'last_sequence': sequence,
                  'captured_at': datetime.now(timezone.utc).isoformat(),
                  'database_name': path.name}
        con.execute('COMMIT')
        return result
    finally:
        con.close()


def normalize_rows(rows: list[dict], today: str) -> list[dict]:
    normalized, seen = [], set()
    for original in rows:
        if not isinstance(original, dict) or any(not isinstance(original.get(k), str) for k in COLUMNS):
            raise StatementError('SF36 rows require all thirteen original text fields')
        r = {k: original[k] for k in COLUMNS}
        for k in ('request_id', 'actor', 'service'):
            if not ID_PATTERN.fullmatch(r[k]):
                raise StatementError('invalid ledger identity: ' + k)
        if r['request_id'] in seen:
            raise StatementError('duplicate ledger request identity')
        seen.add(r['request_id'])
        if r['network'] not in NETWORKS or not ASSET.fullmatch(r['asset']):
            raise StatementError('invalid ledger network/asset')
        if not HEX.fullmatch(r['request_digest']):
            raise StatementError('invalid request digest')
        utc_day(r['day'])
        maximum, actual = parse_amount(r['amount']), parse_amount(r['actual'])
        if maximum < 1 or actual > maximum or r['scheme'] not in ('exact', 'upto'):
            raise StatementError('inconsistent ledger amounts/scheme')
        if r['state'] == 'reserved':
            if actual != 0 or r['receipt_ref'] or r['proof_sha256']:
                raise StatementError('reserved row unexpectedly contains settlement fields')
            settled, pending, released = 0, maximum, 0
        elif r['state'] == 'settled':
            if (not r['receipt_ref'] or len(r['receipt_ref']) > 512 or
                    not HEX.fullmatch(r['proof_sha256']) or
                    (r['scheme'] == 'exact' and actual != maximum)):
                raise StatementError('inconsistent settled row')
            settled, pending, released = actual, 0, maximum - actual
        else:
            raise StatementError('unknown reservation state; update the reader for this schema')
        age = (date.fromisoformat(today) - date.fromisoformat(r['day'])).days
        r.update(zip(MONEY, map(str, (settled, pending, released))))
        r['age_utc_days'] = age if r['state'] == 'reserved' and age >= 0 else None
        normalized.append(r)
    return sorted(normalized, key=lambda r: (r['day'], r['request_id']))


def aggregate(rows: list[dict], dimensions: tuple[str, ...] = ()) -> list[dict]:
    """Never sum unlike assets/networks. Python integers avoid aggregate overflow."""
    keys = ('network', 'asset', *dimensions)
    groups: dict[tuple, dict] = {}
    for r in rows:
        key = tuple(r[k] for k in keys)
        g = groups.setdefault(key, {**dict(zip(keys, key)), 'requests': 0,
                                   'pending_requests': 0, **dict.fromkeys(MONEY, 0)})
        g['requests'] += 1
        g['pending_requests'] += int(r['state'] == 'reserved')
        for name in MONEY:
            g[name] += int(r[name])
    result = []
    for key in sorted(groups):
        g = groups[key]
        g['accounted_base_units'] = str(g[MONEY[0]] + g[MONEY[1]])
        for name in MONEY:
            g[name] = str(g[name])
        result.append(g)
    return result


def parse_labels(value: dict | None) -> dict[tuple, dict]:
    if value is None:
        return {}
    if not isinstance(value, dict) or set(value) != {'assets'} or not isinstance(value['assets'], list):
        raise StatementError('labels must be an object containing an assets array')
    labels = {}
    for item in value['assets']:
        if not isinstance(item, dict) or set(item) != {'network', 'asset', 'symbol', 'decimals'}:
            raise StatementError('each label needs network, asset, symbol and decimals')
        pair = (item['network'], item['asset'])
        if (not isinstance(pair[0], str) or pair[0] not in NETWORKS or
                not isinstance(pair[1], str) or not ASSET.fullmatch(pair[1])):
            raise StatementError('invalid label network/asset')
        if pair in labels:
            raise StatementError('duplicate asset label')
        symbol, decimals = item['symbol'], item['decimals']
        if (not isinstance(symbol, str) or not 1 <= len(symbol) <= 24 or
                any(ord(c) < 32 or ord(c) == 127 for c in symbol) or
                type(decimals) is not int or not 0 <= decimals <= 30):
            raise StatementError('label symbol/decimals invalid')
        labels[pair] = item.copy()
    return labels


def select_rows(rows: list[dict], filters: dict) -> list[dict]:
    allowed = {'from_day', 'through_day', 'actor', 'service', 'network', 'asset', 'state'}
    if not isinstance(filters, dict) or set(filters) - allowed:
        raise StatementError('unknown statement filter')
    for key, value in filters.items():
        if not isinstance(value, str) or not value:
            raise StatementError('filter values must be nonempty strings')
        if key in ('from_day', 'through_day'):
            utc_day(value)
    if filters.get('from_day', '') > filters.get('through_day', '9999-12-31'):
        raise StatementError('from-day is after through-day')
    if 'network' in filters and filters['network'] not in NETWORKS:
        raise StatementError('unsupported filter network')
    if 'state' in filters and filters['state'] not in ('reserved', 'settled'):
        raise StatementError('state must be reserved or settled')
    return [r for r in rows if
            r['day'] >= filters.get('from_day', '0001-01-01') and
            r['day'] <= filters.get('through_day', '9999-12-31') and
            all(r[k] == v for k, v in filters.items() if k not in ('from_day', 'through_day'))]


def build_statement(snapshot: dict, *, filters: dict | None = None,
                    policy: dict | None = None, labels: dict | None = None) -> dict:
    captured = datetime.fromisoformat(snapshot['captured_at'].replace('Z', '+00:00'))
    if captured.tzinfo is None or captured.utcoffset().total_seconds() != 0:
        raise StatementError('snapshot time must be explicitly UTC')
    today = captured.date().isoformat()
    rows = normalize_rows(snapshot['rows'], today)
    selected = select_rows(rows, filters or {})
    parsed_labels = parse_labels(labels)
    limits = validate_policy(policy) if policy is not None else {}
    portfolio = {(g['network'], g['asset']): g for g in aggregate(rows)}
    for pair in limits:
        portfolio.setdefault(pair, {'network': pair[0], 'asset': pair[1], 'requests': 0,
                                    'pending_requests': 0, **dict.fromkeys(MONEY, '0'),
                                    'accounted_base_units': '0'})
    today_usage = {(g['network'], g['asset']): int(g['accounted_base_units'])
                   for g in aggregate([r for r in rows if r['day'] == today])}
    for pair, group in portfolio.items():
        group['today_accounted_base_units'] = str(today_usage.get(pair, 0))
        if pair in limits:
            cap = limits[pair]
            used, day_used = int(group['accounted_base_units']), today_usage.get(pair, 0)
            group['policy'] = {k: str(v) for k, v in cap.items()}
            group['remaining_total_base_units'] = str(max(0, cap['max_total'] - used))
            group['remaining_today_base_units'] = str(max(0, cap['max_per_utc_day'] - day_used))
            group['over_total_base_units'] = str(max(0, used - cap['max_total']))
            group['over_today_base_units'] = str(max(0, day_used - cap['max_per_utc_day']))
    return {
        'schema': SCHEMA, 'captured_at': snapshot['captured_at'], 'today_utc': today,
        'source': {'database_name': snapshot['database_name'], 'reservations': len(rows),
                   'journal_events': snapshot['journal_events'], 'last_sequence': snapshot['last_sequence'],
                   'projection_sha256': hashlib.sha256(canonical(snapshot['rows'])).hexdigest()},
        'basis': 'SF36 ledger projection; no HMAC or independent chain verification performed',
        'date_basis': 'UTC reservation day, not settlement or accounting recognition date',
        'filters': filters or {}, 'rows': selected,
        'selected_totals': aggregate(selected),
        'by_actor': aggregate(selected, ('actor',)),
        'by_service': aggregate(selected, ('service',)),
        'by_reservation_day': aggregate(selected, ('day',)),
        'portfolio': [portfolio[p] for p in sorted(portfolio)],
        'asset_labels': [parsed_labels[p] for p in sorted(parsed_labels)],
        'notes': [
            'Portfolio and policy capacity cover the entire snapshot, unaffected by selection filters.',
            'Reserved maximum is unresolved exposure, not settled spend and not an automatic refund.',
            'Released capacity is an unused authorization maximum, not returned money.',
            'Remaining total/day capacity is not a new purchase approval; other native caps and concurrent work still apply.',
            'Asset labels/decimals are supplied by the operator; no token registry or fiat conversion is used.',
            'Exports contain private actor, service and receipt references. Keep them off public hosting.'
        ]
    }


def csv_cell(value: Any) -> str:
    text = '' if value is None else str(value)
    # Spreadsheet formula injection protection. Numeric base units remain exact
    # decimal bytes; spreadsheet importers must select TEXT to prevent rounding.
    if text and (text[0] in '\t\r\n' or text.lstrip()[:1] in ('=', '+', '-', '@')):
        return "'" + text
    return text


def render_csv(rows: list[dict]) -> str:
    out = io.StringIO(newline='')
    writer = csv.writer(out, lineterminator='\r\n')
    writer.writerow(CSV_FIELDS)
    writer.writerows([csv_cell(r.get(k)) for k in CSV_FIELDS] for r in rows)
    return out.getvalue()


def format_units(value: str, label: dict | None = None) -> str:
    if label is None:
        return value + ' base units'
    precision = label['decimals']
    padded = value.zfill(precision + 1)
    number = padded if precision == 0 else padded[:-precision] + '.' + padded[-precision:]
    return number + ' ' + label['symbol']


