    bytes(manifestFile, 8 * 1024 * 1024, { optional: true }),
    bytes(join(directory, '.atlas-transfer-state.json'), 512 * 1024 * 1024, { optional: true }),
    bytes(join(directory, '.atlas-transfer-complete.json'), 65536, { optional: true }),
